"""v1.6.1 source fixes, run on the hand-edited LIGHT frames only (dark/outdoor are regenerated by variants.py).
   F-01 sprite is inlined into html/ permanently   (see tools/inline_sprite.py)
   F-02 appbar: drop inline padding hacks, aria-labels on icon buttons, on-hero marker
   F-03 .chip misused as 26px label  -> .badge
   F-04 trust/credential rows        -> .badges (wrap)
   F-05 chip rows that scroll        -> .faderow scrollable"""
import sys, glob, re
from bs4 import BeautifulSoup
root = sys.argv[1]
ICON_LABEL = {'i-more':'More options','i-flag':'Report','i-search':'Search','i-call':'Call','i-bell':'Notifications',
              'i-gear':'Settings','i-pencil':'Edit','i-x':'Close','i-send':'Send','i-cam':'Add photo','i-nav':'Navigate','i-cal':'Schedule'}
stats = dict(appbar=0, aria=0, badge=0, trust=0, tiny=0, raw_badge=0)
def raw_fixes(t):
    # F-06 spec floor: caption >= 12px (AC-VD-10); handoff claimed 0 hits, audit found 11px in 10 places
    t, n1 = re.subn(r'font-size:11px', 'font-size:12px', t); t, n2 = re.subn(r'(font:\d+ )11px', r'\g<1>12px', t)
    t = t.replace('height:22px;font-size:12px', 'height:24px;font-size:12px')
    # F-03 in files that are not soup-processed (component sheet, prototype): chip-as-label -> badge
    t, n3 = re.subn(r'<span class="chip" style="height:2[46]px;font-size:12px">', '<span class="badge">', t)
    stats['tiny'] += n1 + n2; stats['raw_badge'] += n3
    return t
for f in glob.glob(f'{root}/html/component-sheet.html') + glob.glob(f'{root}/html/prototype.html'):
    t = open(f).read(); n = raw_fixes(t)
    if n != t: open(f, 'w').write(n)
for f in sorted(glob.glob(f'{root}/html/frames-*.html')):
    if f.endswith(('frames-dark.html','frames-outdoor.html')): continue
    s = BeautifulSoup(raw_fixes(open(f).read()), 'html.parser')
    for ab in s.select('.appbar[style]'):
        st = ab['style'].replace(' ', '')
        if 'padding:4px20px' in st:
            del ab['style']; stats['appbar'] += 1
            if ab.find_parent(class_=['heroband','maphead']): ab['class'] = ab.get('class', []) + ['on-hero']
    for b in s.select('.appbar .back'):
        b['aria-label'] = 'Back'; b['role'] = 'button'; stats['aria'] += 1
    for ib in s.select('.appbar .ico-btn'):
        u = ib.find('use')
        if u and not ib.get('aria-label'):
            lab = ICON_LABEL.get((u.get('href') or '').lstrip('#'))
            if lab: ib['aria-label'] = lab; ib['role'] = 'button'; stats['aria'] += 1
    for c in s.select('span.chip[style*="height:26px"]'):
        c['class'] = ['badge']; del c['style']; stats['badge'] += 1
        for sv in c.find_all('svg'): sv['width'] = sv['height'] = '14'
    # trust tiles: a .spread holding >=2 badges  ->  rating/title row + wrapping .badges row
    for sp in s.select('.tile > .spread'):
        bs = sp.select(':scope > .badge')
        if len(bs) >= 2:
            lead = [c for c in sp.children if getattr(c, 'name', None) and 'badge' not in (c.get('class') or [])]
            wrap = s.new_tag('div', attrs={'class': 'badges', 'style': 'margin-top:10px'})
            for b in bs: wrap.append(b.extract())
            sp.insert_after(wrap); sp['class'] = ['row']; stats['trust'] += 1
    for fr in s.select('.faderow'):
        pass
    open(f, 'w').write(str(s))
print(stats)
